css:
.opencollab-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #21252b;
    background: linear-gradient(170deg, #f4f6fb 0%, #eef1f8 50%, #e9eef6 100%);
    border-radius: 18px;
}

.opencollab-container * {
    box-sizing: border-box;
}

.opencollab-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1a1b3a 0%, #2d2a6e 55%, #166e6b 100%);
    color: #f2f5fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(26, 27, 58, 0.32);
}

.opencollab-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.opencollab-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #8de8c8;
    background: rgba(141, 232, 200, 0.12);
    border: 1px solid rgba(141, 232, 200, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.opencollab-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cfd6ec;
}

.opencollab-orgs {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.opencollab-org {
    flex: 1;
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(33, 37, 43, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.opencollab-org-foundation { border-left: 5px solid #2d2a6e; }
.opencollab-org-community { border-left: 5px solid #166e6b; }

.opencollab-org-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #1a1b3a;
}

.opencollab-org-foundation .opencollab-org-name { color: #3a36a0; }
.opencollab-org-community .opencollab-org-name { color: #11807c; }

.opencollab-org-meta {
    font-size: 0.82rem;
    color: #5a6275;
    line-height: 1.4;
}

.opencollab-org-plus {
    align-self: center;
    font-size: 1.6rem;
    font-weight: 800;
    color: #166e6b;
}

.opencollab-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44495a;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.opencollab-period-counter #currentDay,
.opencollab-period-counter #maxPeriods {
    font-weight: 800;
    color: #11807c;
}

.opencollab-round-name {
    background: rgba(17, 128, 124, 0.13);
    color: #0e6b67;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.opencollab-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #6a3fb0;
    background: rgba(106, 63, 176, 0.12);
    border: 1px solid rgba(106, 63, 176, 0.28);
    padding: 4px 12px;
    border-radius: 999px;
}

.opencollab-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.opencollab-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(33, 37, 43, 0.08);
    border-top: 4px solid #2d2a6e;
}

.opencollab-card-quality { border-top-color: #166e6b; }
.opencollab-card-contain { border-top-color: #3a36a0; }
.opencollab-card-contrib { border-top-color: #c47d12; }
.opencollab-card-backlog { border-top-color: #6a3fb0; }

.opencollab-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    font-weight: 700;
    color: #69728a;
}

.opencollab-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1a1b3a;
    font-variant-numeric: tabular-nums;
}

.opencollab-card-quality .opencollab-value { color: #166e6b; }
.opencollab-card-contain .opencollab-value { color: #3a36a0; }
.opencollab-card-contrib .opencollab-value { color: #c47d12; }
.opencollab-card-backlog .opencollab-value { color: #6a3fb0; }

.opencollab-sublabel {
    font-size: 0.75rem;
    color: #79839a;
    line-height: 1.35;
}

/* Quality KPI is the headline — colour tells the recovery story. */
.opencollab-card-quality.opencollab-quality-danger { border-top-color: #d63b3b; }
.opencollab-card-quality.opencollab-quality-danger .opencollab-value { color: #d63b3b; }
.opencollab-card-quality.opencollab-quality-warn { border-top-color: #c47d12; }
.opencollab-card-quality.opencollab-quality-warn .opencollab-value { color: #c47d12; }
.opencollab-card-quality.opencollab-quality-good { border-top-color: #15a06a; }
.opencollab-card-quality.opencollab-quality-good .opencollab-value { color: #15a06a; }

.opencollab-card-backlog.opencollab-backlog-good .opencollab-value { color: #15a06a; }
.opencollab-card-backlog.opencollab-backlog-danger .opencollab-value { color: #d63b3b; }

.opencollab-meters {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
    margin-bottom: 18px;
}

.opencollab-meter {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e2e6f0;
    color: #44495a;
    padding: 10px 18px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 0.9rem;
}

.opencollab-meter span:last-child {
    font-size: 1rem;
    letter-spacing: 0.3px;
    color: #d63b3b;
    font-weight: 800;
}

.opencollab-meter.opencollab-meter-mid span:last-child { color: #c47d12; }
.opencollab-meter.opencollab-meter-good span:last-child { color: #15a06a; }

.opencollab-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #166e6b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 37, 43, 0.07);
}

.opencollab-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.opencollab-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1a1b3a;
    margin-bottom: 6px;
}

.opencollab-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4154;
}

.opencollab-briefing-text strong { color: #11807c; }
.opencollab-briefing-text em { color: #6a3fb0; font-style: italic; }

.opencollab-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 37, 43, 0.07);
}

.opencollab-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1a1b3a;
    border-bottom: 2px solid #e7eaf2;
    padding-bottom: 8px;
}

.opencollab-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3142;
    margin: 14px 0 6px;
}

.opencollab-container select,
.opencollab-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9d0de;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #21252b;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.opencollab-container select:focus,
.opencollab-container input[type="number"]:focus {
    outline: none;
    border-color: #166e6b;
    box-shadow: 0 0 0 3px rgba(22, 110, 107, 0.16);
}

.opencollab-container select option {
    background-color: #ffffff;
    color: #21252b;
}

.opencollab-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #166e6b;
}

.opencollab-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44495a;
    margin-top: 4px;
}

.opencollab-range-readout span:nth-child(2) {
    color: #166e6b;
    font-weight: 800;
}

.opencollab-event {
    margin-top: 14px;
    background: rgba(196, 125, 18, 0.10);
    border: 1px solid rgba(196, 125, 18, 0.32);
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 0.86rem;
    line-height: 1.45;
    color: #8a5708;
    font-weight: 600;
}

.opencollab-budget-note {
    background: rgba(58, 54, 160, 0.07);
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 0.9rem;
    line-height: 1.45;
    color: #2f3552;
    margin: 4px 0 6px;
}

.opencollab-budget-note strong { color: #3a36a0; font-size: 1.05rem; }

.opencollab-budget-readout {
    font-size: 0.92rem;
    font-weight: 800;
    color: #3a36a0;
    margin: 10px 0 2px;
    padding: 8px 12px;
    background: rgba(58, 54, 160, 0.06);
    border-radius: 9px;
}

.opencollab-budget-readout.opencollab-budget-over {
    color: #d63b3b;
    background: rgba(214, 59, 59, 0.08);
}

.opencollab-hint {
    font-size: 0.8rem;
    color: #79839a;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.opencollab-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.opencollab-container .btn-primary {
    background: linear-gradient(135deg, #2d2a6e 0%, #166e6b 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(45, 42, 110, 0.30);
}

.opencollab-container .btn-primary:hover {
    filter: brightness(1.08);
}

.opencollab-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c9d0de;
    color: #5a6275;
    background: transparent;
}

.opencollab-coach {
    background: linear-gradient(160deg, #1a1b3a 0%, #24235a 100%);
    color: #e2e8f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(26, 27, 58, 0.26);
}

.opencollab-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8de8c8;
    margin-bottom: 8px;
}

.opencollab-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.opencollab-coach-body strong { color: #7fe0cf; }
.opencollab-coach-body em { color: #c9a6f5; font-style: italic; }

.opencollab-history,
.opencollab-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(33, 37, 43, 0.07);
}

.opencollab-history h3,
.opencollab-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1a1b3a;
}

.opencollab-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4154;
}

.opencollab-container table#usfHistoryTable th {
    background: #eef1f8;
    color: #3a36a0;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dce0ee;
}

.opencollab-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef0f5;
    color: #3a4154;
}

.opencollab-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f8fc;
}

.opencollab-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .opencollab-container {
        padding: 14px;
    }
    .opencollab-header h1 {
        font-size: 1.7rem;
    }
    .opencollab-orgs {
        flex-direction: column;
    }
    .opencollab-org-plus {
        transform: rotate(90deg);
    }
    .opencollab-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .opencollab-value {
        font-size: 2rem;
    }
    .opencollab-meters {
        grid-template-columns: 1fr;
    }
    .opencollab-clock {
        margin-left: 0;
    }
    .opencollab-period-counter {
        font-size: 0.88rem;
    }
    .opencollab-meter {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .opencollab-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.oc-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.oc-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #79839a; margin-bottom: 6px; }
.oc-cm-verdict { font-size: 22px; font-weight: 700; color: #21252b; margin-bottom: 8px; }
.oc-cm-score { font-size: 16px; color: #21252b; margin-bottom: 16px; }
.oc-cm-score strong { color: #166e6b; }
.oc-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #79839a; margin-bottom: 8px; }
.oc-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.oc-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.oc-cm-target.oc-cm-met { background: #e7f5f4; color: #12615e; border-color: #b7e0dd; }
.oc-cm-target.oc-cm-missed { background: #fdeceb; color: #9a342c; border-color: #f2c9c4; }
.oc-cm-tick { font-weight: 700; }
.oc-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.oc-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: #f4f6f9; border-radius: 8px; min-width: 96px; }
.oc-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #79839a; }
.oc-cm-metric strong { font-size: 16px; color: #21252b; }
.oc-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.oc-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: #f3f7f7; border-left: 3px solid #166e6b; border-radius: 4px; color: #2b303b; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .oc-cm-metric { min-width: 72px; } .oc-cm-verdict { font-size: 19px; } }

