(function() {
    'use strict';

    class OpenCollaborationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Open Collaboration`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (OpenSavoir / Savoir). ----
            this.QUALITY_BASELINE = 82;   // pre-attack quality index on targeted pages
            this.QUALITY_START = 61;       // surge low
            this.QUALITY_TARGET = 78;      // recovery threshold within 30 days
            this.START_CONTRIB = 48000;    // active contributors
            this.PRIV_REVIEWERS = 1900;    // privileged reviewers — the bottleneck
            this.ATTACK_EDITS = 41000;     // abusive edits in 72h
            this.START_BACKLOG = 14;       // review backlog (days)
            this.BUDGET = 600;             // EUR k emergency response budget
            this.CLASSIFIER_COST = 220;    // EUR k to deploy the classifier
            this.GRANT_AT_RISK = 3.8;      // EUR M institutional grants at risk
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    quality: this.QUALITY_START,      // quality index on targeted pages (/100)
                    contained: 0,                      // % of the 41,000 abusive edits contained
                    contributors: this.START_CONTRIB,  // active contributors
                    backlog: this.START_BACKLOG,        // review backlog (days)
                    trust: 48,                          // community trust & morale (0-100)
                    grant: 35,                          // grantor confidence (0-100)
                    lockedDown: false,                  // chose the blunt instrument
                    bypassedCommunity: false,           // ruled by fiat
                    overAutomated: false,               // auto-revert on the classifier
                    gamedIncentive: false,              // edit-count leaderboard
                    classifierDeployed: false,
                    spend: 0,                           // EUR k committed across rounds
                    missedGrantor: false,
                    qualityHistory: [this.QUALITY_START],
                    containHistory: [0],
                    backlogHistory: [this.START_BACKLOG],
                    contribHistory: [this.START_CONTRIB],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    bottleneck: `volume`,
                    separation: `revertall`,
                    falsepos: `minor`,
                    capacity: 20,
                    lever: `lockdown`,
                    authority: `fiat`,
                    sunset: `indefinite`,
                    tooling: 500,
                    moderators: 60,
                    support: 40,
                    classifier: `autorevert`,
                    incentive: `editcount`,
                    partners: `no`,
                    grantor: `none`,
                    defense: `closed`,
                    standing: `permanent`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const bo = document.getElementById(`bottleneckInput`);
                const se = document.getElementById(`separationInput`);
                const fp = document.getElementById(`falseposInput`);
                const ca = document.getElementById(`capacityInput`);
                if (bo) decisions.bottleneck = bo.value;
                if (se) decisions.separation = se.value;
                if (fp) decisions.falsepos = fp.value;
                if (ca) decisions.capacity = parseInt(ca.value, 10);
                if (!Number.isFinite(decisions.capacity) || decisions.capacity < 0 || decisions.capacity > 100) {
                    warn(`warn_capacity_range`); return false;
                }
            } else if (round === 2) {
                const le = document.getElementById(`leverInput`);
                const au = document.getElementById(`authorityInput`);
                const su = document.getElementById(`sunsetInput`);
                if (le) decisions.lever = le.value;
                if (au) decisions.authority = au.value;
                if (su) decisions.sunset = su.value;
            } else if (round === 3) {
                const to = document.getElementById(`toolingInput`);
                const mo = document.getElementById(`moderatorsInput`);
                const su = document.getElementById(`supportInput`);
                const cl = document.getElementById(`classifierInput`);
                const inc = document.getElementById(`incentiveInput`);
                const pa = document.getElementById(`partnersInput`);
                if (to) decisions.tooling = parseFloat(to.value);
                if (mo) decisions.moderators = parseFloat(mo.value);
                if (su) decisions.support = parseFloat(su.value);
                if (cl) decisions.classifier = cl.value;
                if (inc) decisions.incentive = inc.value;
                if (pa) decisions.partners = pa.value;
                if (!Number.isFinite(decisions.tooling) || !Number.isFinite(decisions.moderators) || !Number.isFinite(decisions.support) ||
                    decisions.tooling < 0 || decisions.moderators < 0 || decisions.support < 0) {
                    warn(`warn_budget_negative`); return false;
                }
                const total = decisions.tooling + decisions.moderators + decisions.support;
                if (total > this.BUDGET) { warn(`warn_budget_over`); return false; }
                if (decisions.classifier !== `none` && decisions.tooling < this.CLASSIFIER_COST) {
                    warn(`warn_classifier_underfunded`); return false;
                }
            } else if (round === 4) {
                const gr = document.getElementById(`grantorInput`);
                const de = document.getElementById(`defenseInput`);
                const st = document.getElementById(`standingInput`);
                const cv = document.getElementById(`convictionInput`);
                if (gr) decisions.grantor = gr.value;
                if (de) decisions.defense = de.value;
                if (st) decisions.standing = st.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let qualityDelta = 0, containDelta = 0, backlogDelta = 0, trustDelta = 0, grantDelta = 0;
            let contribDelta = 0;   // change in active contributors (can be negative)
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose — the real bottleneck is reviewer capacity, not edit volume.
                switch (d.bottleneck) {
                    case `reviewers`: trustDelta += 4; backlogDelta -= 1; coachKey = `coach_r1_reviewers`; break;
                    case `volume`: trustDelta -= 2; coachKey = `coach_r1_volume`; break;
                    case `software`: trustDelta -= 1; coachKey = `coach_r1_software`; break;
                    case `press`: grantDelta -= 2; trustDelta -= 2; coachKey = `coach_r1_press`; break;
                }

                // Separating coordinated abuse from good-faith activity.
                switch (d.separation) {
                    case `signals`: containDelta += 6; qualityDelta += 2; trustDelta += 3; break;
                    case `revertall`: containDelta += 8; qualityDelta += 2; trustDelta -= 8; contribDelta -= 600; coachKey = `coach_r1_revertall`; break;
                    case `ignore`: trustDelta -= 6; contribDelta -= 400; coachKey = `coach_r1_ignore`; break;
                }

                // False-positive risk weighting.
                switch (d.falsepos) {
                    case `primary`: trustDelta += 5; break;
                    case `minor`: trustDelta -= 2; break;
                    case `none`: trustDelta -= 5; contribDelta -= 300; break;
                }

                // Reviewer surge-capacity mobilised this week.
                if (d.capacity >= 50) { backlogDelta -= 2; qualityDelta += 2; }
                else if (d.capacity <= 10) { backlogDelta += 1; }

                summaryKey = (d.bottleneck === `reviewers` && d.separation === `signals` && d.falsepos === `primary`) ? `sum_r1_good` : `sum_r1_weak`;
                if (summaryKey === `sum_r1_good`) coachKey = `coach_r1_sharp`;
            } else if (round === 2) {
                // The openness vs control choice (Common Errors 1 & 2).
                switch (d.lever) {
                    case `pending`:
                        // Proportionate: targeted pending-changes + citation rules — the modelled lever.
                        qualityDelta += 9; containDelta += 16; backlogDelta -= 2; trustDelta += 2; grantDelta += 6;
                        coachKey = `coach_r2_pending`;
                        break;
                    case `lockdown`:
                        // The blunt instrument (decision tree #1): quality up fast, community broken.
                        ds.lockedDown = true;
                        qualityDelta += 12; containDelta += 22; backlogDelta -= 4;
                        trustDelta -= 22; contribDelta -= 1800; grantDelta += 2;
                        coachKey = `coach_r2_lockdown`;
                        break;
                    case `throttle`:
                        // Too light for a coordinated surge of this scale.
                        qualityDelta += 3; containDelta += 7; backlogDelta += 1; trustDelta += 2;
                        coachKey = `coach_r2_throttle`;
                        break;
                    case `nothing`:
                        // Under-reaction — the surge wins (decision tree #4).
                        qualityDelta -= 4; containDelta += 1; backlogDelta += 3; trustDelta -= 4;
                        coachKey = `coach_r2_nothing`;
                        break;
                }

                // Who governs (decision tree #2 — Jemielniak's core point).
                switch (d.authority) {
                    case `community`: trustDelta += 8; backlogDelta -= 1; grantDelta += 1; break;
                    case `hybrid`: trustDelta += 5; grantDelta += 3; break;
                    case `fiat`: ds.bypassedCommunity = true; trustDelta -= 16; contribDelta -= 900; coachKey = `coach_r2_fiat`; break;
                }

                // Sunset / review date legitimises emergency measures.
                if (d.sunset === `sunset`) { trustDelta += 5; grantDelta += 3; }
                else { trustDelta -= 4; if (d.lever === `lockdown` || d.lever === `pending`) grantDelta -= 2; }

                summaryKey = (d.lever === `pending` && (d.authority === `community` || d.authority === `hybrid`) && d.sunset === `sunset`) ? `sum_r2_good` :
                             (d.lever === `lockdown` ? `sum_r2_lockdown` :
                             (d.authority === `fiat` ? `sum_r2_fiat` :
                             (d.lever === `nothing` ? `sum_r2_under` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Mobilise reviewer capacity (Common Errors 3, 4, 5).
                ds.spend = Math.min(this.BUDGET, ds.spend + d.tooling + d.moderators + d.support);
                ds.classifierDeployed = (d.classifier !== `none`);

                // Contractor moderators directly cut the backlog (bought attention).
                if (d.moderators >= 200) { backlogDelta -= 4; containDelta += 8; }
                else if (d.moderators >= 80) { backlogDelta -= 2; containDelta += 4; }
                else { backlogDelta += 1; }

                // Classifier wiring (decision tree #3 — augment vs auto-revert).
                switch (d.classifier) {
                    case `augment`: containDelta += 14; backlogDelta -= 3; qualityDelta += 5; trustDelta += 3; coachKey = `coach_r3_augment`; break;
                    case `autorevert`: ds.overAutomated = true; containDelta += 18; qualityDelta += 4; backlogDelta -= 2; trustDelta -= 18; contribDelta -= 1400; coachKey = `coach_r3_autorevert`; break;
                    case `none`: backlogDelta += 2; coachKey = `coach_r3_noclassifier`; break;
                }

                // Incentive design (decision tree #5 — Goodhart's law).
                switch (d.incentive) {
                    case `quality`: backlogDelta -= 3; qualityDelta += 6; trustDelta += 6; contribDelta += 400; break;
                    case `editcount`: ds.gamedIncentive = true; backlogDelta -= 1; qualityDelta -= 3; trustDelta -= 4; coachKey = `coach_r3_gamed`; break;
                    case `none`: backlogDelta += 2; trustDelta -= 4; contribDelta -= 300; coachKey = `coach_r3_nogoodwill`; break;
                }

                // Outside expert eyes add credible capacity.
                if (d.partners === `yes`) { backlogDelta -= 2; qualityDelta += 3; grantDelta += 4; }

                // Community support funding cushions morale.
                if (d.support >= 120) { trustDelta += 5; contribDelta += 300; }
                else if (d.support <= 0) { trustDelta -= 3; }

                summaryKey = (d.classifier === `augment` && d.incentive === `quality` && d.moderators >= 80) ? `sum_r3_good` :
                             (d.classifier === `autorevert` ? `sum_r3_auto` :
                             (d.incentive === `editcount` ? `sum_r3_gamed` :
                             (d.incentive === `none` ? `sum_r3_goodwill` : `sum_r3_weak`)));
                if (summaryKey === `sum_r3_good` && coachKey === `coach_r3_augment`) coachKey = `coach_r3_balanced`;
            } else if (round === 4) {
                // Recover & sustain — institutional containment (decision tree #6).
                switch (d.grantor) {
                    case `plan`: grantDelta += 22; trustDelta += 3; coachKey = `coach_r4_plan`; break;
                    case `late`: grantDelta += 6; coachKey = `coach_r4_late`; break;
                    case `none`: ds.missedGrantor = true; grantDelta -= 18; coachKey = `coach_r4_nograntor`; break;
                }

                // The open-model defense to the board.
                switch (d.defense) {
                    case `own`: trustDelta += 7; grantDelta += 6; qualityDelta += 2; if (d.grantor === `plan`) coachKey = `coach_r4_own`; break;
                    case `closed`: trustDelta -= 5; grantDelta += 2; coachKey = `coach_r4_closed`; break;
                    case `deny`: trustDelta -= 8; grantDelta -= 4; coachKey = `coach_r4_deny`; break;
                }

                // Standing anti-abuse governance design for the next surge.
                switch (d.standing) {
                    case `community`: trustDelta += 8; grantDelta += 6; qualityDelta += 3; contribDelta += 500; break;
                    case `permanent`: ds.lockedDown = true; trustDelta -= 14; contribDelta -= 1200; grantDelta -= 2; coachKey = `coach_r4_permanent`; break;
                    case `none`: trustDelta -= 4; grantDelta -= 4; break;
                }

                if (d.conviction >= 60) { trustDelta += 3; }
                else if (d.conviction <= 25) { trustDelta -= 3; }

                summaryKey = (d.grantor === `plan` && d.defense === `own` && d.standing === `community`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply core deltas (clamped). ----
            ds.quality = Math.max(0, Math.min(100, Math.round((ds.quality + qualityDelta) * 10) / 10));
            ds.contained = Math.max(0, Math.min(100, Math.round(ds.contained + containDelta)));
            ds.backlog = Math.max(0, Math.round((ds.backlog + backlogDelta) * 10) / 10);
            ds.trust = Math.max(0, Math.min(100, Math.round(ds.trust + trustDelta)));
            ds.grant = Math.max(0, Math.min(100, Math.round(ds.grant + grantDelta)));

            // Contributors drift with morale: low trust accelerates the existing decline.
            if (ds.trust < 35) contribDelta -= 400;
            else if (ds.trust >= 70) contribDelta += 200;
            ds.contributors = Math.max(0, Math.round(ds.contributors + contribDelta));

            // Each lost reviewer ≈ 40 quality edits/month: a collapsing community
            // caps how high quality can climb (you cannot out-tool an exodus).
            const contribShare = ds.contributors / this.START_CONTRIB;     // ~1.0 healthy
            if (contribShare < 0.92) {
                const cap = Math.round((this.QUALITY_TARGET + (contribShare - 0.88) * 120) * 10) / 10;
                if (ds.quality > cap) ds.quality = Math.max(this.QUALITY_START - 4, cap);
            }

            ds.qualityHistory.push(ds.quality);
            ds.containHistory.push(ds.contained);
            ds.backlogHistory.push(ds.backlog);
            ds.contribHistory.push(ds.contributors);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            // (domainState.performance.overallScore, then domainState.score). Identical formula to
            // the completion scorecard (see _composite), so per-round score == final composite.
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                quality: ds.quality,
                qualityDelta: Math.round(qualityDelta * 10) / 10,
                contained: ds.contained,
                contributors: ds.contributors,
                backlog: ds.backlog,
                trust: ds.trust,
                grant: ds.grant,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _trustLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 65) return t(`trust_strong`);
            if (v >= 40) return t(`trust_strained`);
            return t(`trust_fracturing`);
        }

        _grantLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 65) return t(`grant_secure`);
            if (v >= 40) return t(`grant_atrisk`);
            return t(`grant_freezing`);
        }

        _fmtContrib(v) {
            const n = Number(v);
            const k = Math.round(n / 100) / 10;       // thousands, one decimal
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = k.toFixed(1);
            return (lang === `es` ? s.replace(`.`, `,`) : s) + `k`;
        }

        _fmtQuality(v) {
            return String(Math.round(Number(v)));
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`qualityDisplay`, `domainState.quality`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.opencollab-card-quality`);
                if (card) {
                    card.classList.toggle(`opencollab-quality-good`, n >= self.QUALITY_TARGET);
                    card.classList.toggle(`opencollab-quality-warn`, n >= 70 && n < self.QUALITY_TARGET);
                    card.classList.toggle(`opencollab-quality-danger`, n < 70);
                }
                return self._fmtQuality(n);
            });

            uiManager.bind(`containDisplay`, `domainState.contained`, (v) => `${Math.round(Number(v))}%`);
            uiManager.bind(`contribDisplay`, `domainState.contributors`, (v) => self._fmtContrib(v));

            uiManager.bind(`backlogDisplay`, `domainState.backlog`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.opencollab-card-backlog`);
                if (card) {
                    card.classList.toggle(`opencollab-backlog-good`, n <= 4);
                    card.classList.toggle(`opencollab-backlog-danger`, n >= 12);
                }
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                const s = (Math.round(n * 10) / 10).toString();
                return (lang === `es` ? s.replace(`.`, `,`) : s) + `d`;
            });

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const n = Number(v);
                const m = document.querySelectorAll(`.opencollab-meter`)[0];
                if (m) {
                    m.classList.toggle(`opencollab-meter-good`, n >= 65);
                    m.classList.toggle(`opencollab-meter-mid`, n >= 40 && n < 65);
                }
                return self._trustLabel(n);
            });

            uiManager.bind(`grantDisplay`, `domainState.grant`, (v) => {
                const n = Number(v);
                const m = document.querySelectorAll(`.opencollab-meter`)[1];
                if (m) {
                    m.classList.toggle(`opencollab-meter-good`, n >= 65);
                    m.classList.toggle(`opencollab-meter-mid`, n >= 40 && n < 65);
                }
                return self._grantLabel(n);
            });

            // Reviewer-capacity slider readout (Round 1).
            const ca = document.getElementById(`capacityInput`);
            const caReadout = document.getElementById(`capacityReadout`);
            if (ca && caReadout) {
                caReadout.textContent = ca.value;
                ca.addEventListener(`input`, function() { caReadout.textContent = ca.value; });
            }

            // Budget allocation readout (Round 3) — live total of the €600k split.
            const to = document.getElementById(`toolingInput`);
            const mo = document.getElementById(`moderatorsInput`);
            const su = document.getElementById(`supportInput`);
            const allocReadout = document.getElementById(`allocatedReadout`);
            const recompute = function() {
                if (!allocReadout) return;
                const total = (parseFloat(to && to.value) || 0) + (parseFloat(mo && mo.value) || 0) + (parseFloat(su && su.value) || 0);
                allocReadout.textContent = Math.round(total);
                const box = allocReadout.closest(`.opencollab-budget-readout`);
                if (box) box.classList.toggle(`opencollab-budget-over`, total > self.BUDGET);
            };
            [to, mo, su].forEach(function(el) { if (el) el.addEventListener(`input`, recompute); });
            recompute();
        }

        getChartConfig() {
            return {
                savoirChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Quality index (targeted pages)`,
                                data: [],
                                borderColor: `#166e6b`,
                                backgroundColor: `rgba(22,110,107,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#166e6b`,
                                yAxisID: `y`
                            },
                            {
                                label: `Disinformation contained (%)`,
                                data: [],
                                borderColor: `#3a36a0`,
                                backgroundColor: `rgba(58,54,160,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#3a36a0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Review backlog (days)`,
                                data: [],
                                borderColor: `#6a3fb0`,
                                backgroundColor: `rgba(106,63,176,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a3fb0`,
                                yAxisID: `y1`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
