                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#79839a` }, grid: { color: `rgba(33,37,43,0.06)` },
                                title: { display: true, text: `Quality / Contained (0–100)`, color: `#79839a` }
                            },
                            y1: {
                                beginAtZero: true, max: 20, position: `right`,
                                ticks: { color: `#6a3fb0` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: `Backlog (days)`, color: `#6a3fb0` }
                            },
                            x: {
                                ticks: { color: `#79839a` }, grid: { color: `rgba(33,37,43,0.04)` },
                                title: { display: true, text: `Round`, color: `#79839a` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.qualityHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                savoirChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.qualityHistory.map((v) => Math.round(v)) },
                        { data: ds.containHistory },
                        { data: ds.backlogHistory.map((v) => Math.round(v * 10) / 10) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula, extracted so calculateResults (per round)
            // and getPerformanceSummary (completion) produce an identical number.
            const quality = Math.round(ds.quality);
            const contained = Math.round(ds.contained);
            const backlog = Math.round(ds.backlog * 10) / 10;
            const trust = Math.round(ds.trust);
            const grant = Math.round(ds.grant);
            const backlogScore = Math.max(0, 100 - backlog * 6);
            return Math.round(quality * 0.30 + contained * 0.18 + trust * 0.22 + grant * 0.15 + backlogScore * 0.15);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite
                : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];

            const chip = function (ok, label) {
                return '<div class="oc-cm-target ' + (ok ? 'oc-cm-met' : 'oc-cm-missed') + '">'
                    + '<span class="oc-cm-tick">' + (ok ? '✓' : '✗') + '</span>'
                    + '<span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.recovered, t('tgt_quality'))
                + chip(!!summary.containedWell, t('tgt_contained'))
                + chip(!!summary.communityHeld, t('tgt_community'))
                + chip(!!summary.funded, t('tgt_funded'))
                + chip(!!summary.backlogCleared, t('tgt_backlog'));

            const metric = function (label, val) {
                return '<div class="oc-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const contribStr = (typeof this._fmtContrib === 'function' && summary.contributors != null)
                ? this._fmtContrib(summary.contributors)
                : (summary.contributors != null ? summary.contributors : '-');
            const metrics = ''
                + metric(t('kpi_quality'), (summary.quality != null ? summary.quality : '-') + '/100')
                + metric(t('kpi_contained'), (summary.contained != null ? summary.contained : '-') + '%')
                + metric(t('kpi_trust'), (summary.trust != null ? summary.trust : '-') + '/100')
                + metric(t('kpi_grant'), (summary.grant != null ? summary.grant : '-') + '/100')
                + metric(t('kpi_backlog'), (summary.backlog != null ? summary.backlog : '-') + 'd')
                + metric(t('kpi_contrib'), contribStr);

            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');

            return ''
                + '<div class="oc-cm">'
                +   '<div class="oc-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="oc-cm-verdict">' + verdict + '</div>'
                +   '<div class="oc-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="oc-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="oc-cm-targets">' + targets + '</div>'
                +   '<div class="oc-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="oc-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const quality = Math.round(ds.quality);
            const contained = Math.round(ds.contained);
            const contributors = Math.round(ds.contributors);
            const backlog = Math.round(ds.backlog * 10) / 10;
            const trust = Math.round(ds.trust);
            const grant = Math.round(ds.grant);

            const recovered = quality >= this.QUALITY_TARGET;       // hit the 78 cliff
            const containedWell = contained >= 40;  // v1.1.0 FIX D (was >=70; unreachable - see report)
            const communityHeld = trust >= 55 && (contributors / this.START_CONTRIB) >= 0.93;
            const funded = grant >= 60;
            const backlogCleared = backlog <= 5;

            // Composite: quality, containment, community, funding, backlog — balanced.
            // v1.1.0 FIX A - delegated to the shared _composite(ds) helper so the persisted
            // per-round score and this completion composite are identical by construction.
            const composite = this._composite(ds);

            let pattern = `mixed`;
            if (ds.lockedDown && trust < 45) pattern = `closed`;
            else if (ds.bypassedCommunity && trust < 50) pattern = `fiat`;
            else if (ds.overAutomated && trust < 50) pattern = `overauto`;
            else if (recovered && communityHeld && funded) pattern = `commons`;
            else if (!recovered && ds.contributors >= this.START_CONTRIB * 0.95) pattern = `underreact`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (recovered && communityHeld && containedWell && funded && composite >= 72) perfKey = `grade_defended`;
            else if (recovered && communityHeld && funded) perfKey = `grade_contained`;
            else if (ds.lockedDown && !communityHeld) perfKey = `grade_blunt`;
            else if (ds.bypassedCommunity && !communityHeld) perfKey = `grade_forfeited`;
            else if (ds.overAutomated && !communityHeld) perfKey = `grade_overreach`;
            else if (composite >= 52) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (recovered && communityHeld && containedWell && funded) insights.push(window.mySimulation.t(`insight_commons`));
            else if (pattern === `closed`) insights.push(window.mySimulation.t(`insight_closed`));
            else if (pattern === `fiat`) insights.push(window.mySimulation.t(`insight_fiat`));
            else if (pattern === `overauto`) insights.push(window.mySimulation.t(`insight_overauto`));
            else if (pattern === `underreact`) insights.push(window.mySimulation.t(`insight_underreact`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!recovered) insights.push(window.mySimulation.t(`insight_quality_miss`));
            if (ds.gamedIncentive) insights.push(window.mySimulation.t(`insight_gamed`));
            if (ds.missedGrantor) insights.push(window.mySimulation.t(`insight_grantor`));
            if ((contributors / this.START_CONTRIB) < 0.9) insights.push(window.mySimulation.t(`insight_exodus`));
            if (recovered && communityHeld && backlog > 8) insights.push(window.mySimulation.t(`insight_backlog`));

            return {
                gradeKey: perfKey,
                score: composite,
                quality: quality,
                contained: contained,
                contributors: contributors,
                backlog: backlog,
                trust: trust,
                grant: grant,
                recovered: recovered,
                containedWell: containedWell,
                communityHeld: communityHeld,
                funded: funded,
                backlogCleared: backlogCleared,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.contributors < this.START_CONTRIB * 0.9) return window.mySimulation.t(`hint_exodus`);
            if (ds.lockedDown && ds.trust < 40) return window.mySimulation.t(`hint_lockdown`);
            if (ds.overAutomated && ds.trust < 45) return window.mySimulation.t(`hint_overauto`);
            if (ds.bypassedCommunity && ds.trust < 45) return window.mySimulation.t(`hint_fiat`);
            if (ds.quality < this.QUALITY_TARGET && state.currentPeriod >= 3) return window.mySimulation.t(`hint_quality`);
            if (ds.backlog >= 12 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_backlog`);
            if (ds.quality >= this.QUALITY_TARGET && ds.trust >= 60 && ds.grant >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

